import './building.js';
import {refreshCompact} from './compact.js';
const $=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n).toLocaleString('en-GB');
let rows=[],boundaries=[],meta={},filtered=[],caseIndex=0,showPercent=false,after=true,timer=null;
let releases={},activeRelease='supplied',activePairs=[],categories=[],reasonKey='',pairIndex=0;
const state={borough:'',year:'',outcome:'',category:'',cohort:'all',days:null,storeys:'',heritage:'',homes:''};
const bins=[{label:'0–28',min:0,max:28},{label:'29–56',min:29,max:56},{label:'57–84',min:57,max:84},{label:'85–112',min:85,max:112},{label:'113–180',min:113,max:180},{label:'181–365',min:181,max:365},{label:'366+',min:366,max:Infinity}];
const aliases={'City of London':'City','Kensington and Chelsea':'Kensington','Kingston upon Thames':'Kingston','Richmond upon Thames':'Richmond','Westminster':'Westminster'};
const mapKey=n=>aliases[n]||n;
function validTime(r){return r.days!==null&&Number.isFinite(r.days)&&r.days>=0&&!!r.date&&!!r.decided&&Number.isFinite(Date.parse(r.date))&&Number.isFinite(Date.parse(r.decided));}
function matches(r,omit=''){return (omit==='borough'||!state.borough||r.borough===state.borough)&&(omit==='year'||!state.year||r.date.startsWith(state.year))&&(omit==='outcome'||!state.outcome||(r.status||'Unknown')===state.outcome)&&(!state.category||r.type===state.category)&&(state.cohort==='all'||state.cohort==='house'&&r.screen==='House wording'||state.cohort==='verified'&&r.verified===true)&&(omit==='days'||state.days===null||validTime(r)&&r.days>=bins[state.days].min&&r.days<=bins[state.days].max)&&(!state.storeys||r.verified&&r.storeys===Number(state.storeys))&&(!state.heritage||r.verified&&r.heritage===state.heritage)&&(!state.homes||r.verified&&r.proposedHomes===Number(state.homes));}
function scopeRows(omit){return rows.filter(r=>matches(r,omit));}
function summarize(rs){let p=0,r=0;rs.forEach(x=>{if(x.status==='Permitted')p++;if(x.status==='Rejected')r++});const times=rs.filter(validTime).map(x=>x.days).sort((a,b)=>a-b);const med=times.length?(times[Math.floor((times.length-1)/2)]+times[Math.ceil((times.length-1)/2)])/2:null;return {n:rs.length,p,r,denom:p+r,rate:p+r?p/(p+r)*100:null,times,median:med};}
function safeUrl(v){try{let u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:null}catch{return null}}
function date(v){if(!v)return 'Not recorded';const d=new Date(v+'T12:00:00');return Number.isNaN(d.getTime())?v:d.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});}
function setFilter(key,value){state[key]=value;if($(key))$(key).value=value;render();}
function populateControls(){function opts(id,vals){$(id).innerHTML=$(id).options[0].outerHTML+vals.map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('')}
 opts('borough',[...new Set(rows.map(r=>r.borough))].sort());opts('year',[...new Set(rows.map(r=>r.date.slice(0,4)))].filter(Boolean).sort().reverse());opts('outcome',[...new Set(rows.map(r=>r.status||'Unknown'))].filter(Boolean).sort());opts('category',[...new Set(rows.map(r=>r.type))].filter(Boolean).sort());
}
function initControls(){
 ['borough','year','outcome','category','storeys','heritage','homes'].forEach(key=>$(key).addEventListener('change',()=>setFilter(key,$(key).value)));
 document.querySelectorAll('[data-cohort]').forEach(b=>b.onclick=()=>{state.cohort=b.dataset.cohort;render()});
 $('reset').onclick=()=>{Object.assign(state,{borough:'',year:'',outcome:'',category:'',cohort:'all',days:null,storeys:'',heritage:'',homes:''});for(const k of ['borough','year','outcome','category','storeys','heritage','homes'])$(k).value='';render()};
 $('mapMetric').onchange=renderMap; $('rankView').onclick=()=>{setView(false);refreshCompact()};$('mapView').onclick=()=>{setView(true);refreshCompact()};$('outcomeDisplay').onclick=()=>{showPercent=!showPercent;$('outcomeDisplay').textContent=showPercent?'Show counts':'Show percentages';$('outcomeDisplay').setAttribute('aria-pressed',String(showPercent));renderOutcomes()};$('clearDays').onclick=()=>setFilter('days',null);
 $('prevCase').onclick=()=>{caseIndex=Math.max(0,caseIndex-1);renderCase();refreshCompact()};$('nextCase').onclick=()=>{caseIndex=Math.min(filtered.length-1,caseIndex+1);renderCase();refreshCompact()};$('caseSelect').onchange=()=>{caseIndex=Number($('caseSelect').value);renderCase();refreshCompact()};
 $('release').onchange=()=>activateRelease($('release').value);$('releaseSource').onclick=()=>showSheet('sources');$('caseProvenance').onclick=()=>showSheet('sources');$('reasonCategory').onchange=()=>{reasonKey=$('reasonCategory').value;renderReasons();refreshCompact()};$('sizeMeasure').onchange=renderSizes;$('pairSelect').onchange=()=>{pairIndex=Number($('pairSelect').value);renderPair();refreshCompact()};$('prevPair').onclick=()=>{pairIndex=Math.max(0,pairIndex-1);renderPair();refreshCompact()};$('nextPair').onclick=()=>{pairIndex=Math.min(activePairs.length-1,pairIndex+1);renderPair();refreshCompact()};
}
function render(){const oldId=filtered[caseIndex]?.id;filtered=scopeRows();caseIndex=filtered.findIndex(r=>r.id===oldId);if(caseIndex<0)caseIndex=Math.max(0,filtered.findIndex(r=>r.screen==='House wording'&&r.type==='Full'));const s=summarize(filtered);
 $('scope').textContent=(state.borough||'London').toUpperCase()+' / CURRENT SELECTION';$('selectionTitle').textContent=state.cohort==='verified'&&s.n===0?'The next layer is evidence.':state.borough?'A closer look at '+state.borough+'.':'Follow the proposals.';
 $('count').textContent=fmt(s.n);$('countDenom').textContent=`of ${fmt(rows.length)} ${activeRelease==='supplied'?'text-screened conversion candidates':'broad keyword candidates'}`;
 $('rate').textContent=s.rate===null?'—':(100-s.rate).toFixed(1)+'%';$('permittedSegment').style.width=s.denom?(s.p/s.denom*100)+'%':'0';$('permittedSegment').parentElement.style.opacity=s.denom?'1':'.25';$('rateDenom').textContent=s.denom?`${fmt(s.r)} rejected / ${fmt(s.denom)} permitted + rejected`:'No permitted / rejected records in this selection';
 $('median').textContent=s.median===null?'—':fmt(Math.round(s.median*10)/10);$('timeCoverage').textContent=`${fmt(s.times.length)} / ${fmt(s.n)} records have usable intervals`;
 $('interpretation').textContent=s.n===0?(state.cohort==='verified'?'No document-verified conversions are available yet. Switch to candidates to investigate the source records.':'No records match these filters. Broaden the selection to continue.'):`${fmt(s.n-s.denom)} other-status records are outside the refused-share denominator. These are application records, not completed homes.`;
 document.querySelectorAll('[data-cohort]').forEach(b=>{b.classList.toggle('active',b.dataset.cohort===state.cohort);b.setAttribute('aria-pressed',String(b.dataset.cohort===state.cohort))});
 $('verifiedCount').textContent=fmt(filtered.filter(r=>r.verified).length);renderChips();renderAuditWarning();renderRank();renderYears();renderMap();renderOutcomes();renderTimes();renderCaseOptions();renderCase();renderTable();renderReasons();renderSizes();renderRetries();refreshCompact();
}
function setView(map){$('rankPanel').hidden=map;$('mapPanel').hidden=!map;for(const [id,on] of [['rankView',!map],['mapView',map]]){$(id).classList.toggle('active',on);$(id).setAttribute('aria-pressed',String(on))}}
function renderRank(){const base=scopeRows('borough'),groups={};base.forEach(r=>(groups[r.borough]??=[]).push(r));const stats=Object.entries(groups).map(([name,rs])=>({name,...summarize(rs)})).sort((a,b)=>(b.denom>=20)-(a.denom>=20)||(b.denom>=20?(b.r/b.denom-a.r/a.denom):b.n-a.n));const eligible=stats.filter(s=>s.denom>=20);const overall=summarize(base);const chosen=stats.find(s=>s.name===state.borough);let text=eligible.length?`${eligible.length} authorities have at least 20 permitted or rejected records. Compare the recorded refused share; click a bar to select.`:'No authority has 20 permitted or rejected records under these filters.';if(chosen)text=`${chosen.name}: ${chosen.r} rejected of ${chosen.denom} permitted + rejected records${chosen.denom<20?' — small sample.':'.'}`;$('boroughInsight').textContent=text;
 $('boroughRank').innerHTML=stats.length?stats.map(s=>{const rate=s.denom?s.r/s.denom*100:null;return `<button class="rank-row ${s.denom<20?'low':''} ${state.borough===s.name?'active':''}" data-authority="${esc(s.name)}" aria-pressed="${state.borough===s.name}" aria-label="${esc(s.name)}: ${s.r} rejected of ${s.denom} permitted or rejected records${s.denom<20?', share suppressed':''}"><span class="rank-name">${esc(s.name)}</span><span class="rank-track"><span class="rank-fill" style="display:block;width:${s.denom>=20?rate:0}%"></span></span><strong>${s.denom>=20?Math.round(rate)+'%':'—'}</strong><small>n=${fmt(s.denom)}</small></button>`}).join(''):'<p class="empty-state">No matching records. Try another cohort or reset the filters.</p>';
 $('boroughRank').querySelectorAll('[data-authority]').forEach(b=>b.onclick=()=>setFilter('borough',state.borough===b.dataset.authority?'':b.dataset.authority));
}
function renderYears(){const base=scopeRows('year');const years=[...new Set(rows.map(r=>r.date.slice(0,4)))].filter(Boolean).sort();const stats=years.map(y=>({year:y,...summarize(base.filter(r=>r.date.startsWith(y)))}));const max=Math.max(1,...stats.map(s=>s.n));$('yearChart').style.gridTemplateColumns=`repeat(${years.length},minmax(0,1fr))`;const chosen=state.year?stats.find(s=>s.year===state.year):null;$('yearHeadline').textContent=state.year?`A closer look at ${state.year}.`:'How has the application picture changed?';$('yearInsight').textContent=chosen?`${state.borough||'London'}: ${fmt(chosen.n)} candidate applications with a ${state.year} recorded start date.`:`${state.borough||'London'}: ${fmt(base.length)} candidate applications across the available start years. Click a year to filter.`;
 $('yearChart').innerHTML=stats.map(s=>`<button class="year-column ${state.year===s.year?'active':''}" data-year="${s.year}" aria-pressed="${state.year===s.year}" aria-label="${s.year}: ${s.n} applications; ${s.p} permitted, ${s.r} rejected, ${s.n-s.denom} other or unknown"><span class="year-total">${fmt(s.n)}</span><span class="year-stack"><span class="year-segment other" style="height:${(s.n-s.denom)/max*175}px"></span><span class="year-segment rejected" style="height:${s.r/max*175}px"></span><span class="year-segment" style="height:${s.p/max*175}px"></span></span><span class="year-label">${s.year}${s.year==='2026'?'*':''}</span><span class="year-share">${s.denom?Math.round(s.r/s.denom*100)+'% rejected':'No P/R records'}</span></button>`).join('');$('yearChart').querySelectorAll('[data-year]').forEach(b=>b.onclick=()=>setFilter('year',state.year===b.dataset.year?'':b.dataset.year));$('yearCoverage').textContent=`All filters except year apply. Annual refusal shares use permitted + rejected records only. Source coverage and pending decisions affect comparisons; this is not a complete census. ${activeRelease==='supplied'?'Start dates through 30 October 2026; *2026 is a partial year. Supplied 7 November 2026.':'Snapshot: 5 October 2026.'}`;
}
function renderAuditWarning(){const rs=scopeRows('outcome'),flagged=rs.filter(r=>/^(approved|granted|permission granted)/i.test(r.decision||'')&&r.status!=='Permitted');document.querySelectorAll('[data-outcome-audit]').forEach(el=>{el.hidden=!flagged.length;el.textContent=flagged.length?`Outcome audit needed: ${fmt(flagged.length)} of ${fmt(rs.length)} records in this scope have approval wording but a normalised status other than Permitted. Refused shares exclude those records. Treat this as a source-status comparison, not a reliable borough refusal rate.`:'';});}
const sheetTitles={overview:'Overview',london:'Boroughs',when:'Annual trends',decisions:'Decisions & time',evidence:'Evidence gaps',reasons:'Refusal reasons',sizes:'Size & layouts',retries:'Second attempt',concept:'Building model',spotlight:'Source records',sources:'Data & sources'};
