function renderTable(){$('tableCount').textContent=fmt(filtered.length)+' matching';$('caseTable').innerHTML=filtered.slice(0,50).map((r,i)=>`<tr><td>${esc(r.ref)}</td><td>${esc(r.borough)}</td><td>${esc(r.type)}</td><td>${esc(r.status)}</td><td>${validTime(r)?fmt(r.days):'Unknown'}</td><td><button data-row="${i}">Read case ↗</button></td></tr>`).join('')||'<tr><td colspan="6">No matching records.</td></tr>';$('caseTable').querySelectorAll('[data-row]').forEach(b=>b.onclick=()=>{caseIndex=Number(b.dataset.row);renderCase();showSheet('spotlight')})}
function download(){const fields=['id','ref','borough','description','type','status','decision','date','decided','days','url','screen','verified','storeys','heritage','reportedStoreys','reportedDwellings','sourceDecision'];const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';const content=[fields.join(','),...filtered.map(r=>fields.map(f=>cell(r[f])).join(','))].join('\r\n');const u=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='plan-check-'+activeRelease+'-selection.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}$('download').onclick=download;
for(const id of ['methodOpen','methodBottom','footerMethod'])$(id).onclick=()=>$('method').showModal();$('closeMethod').onclick=()=>$('method').close();$('method').onclick=e=>{if(e.target===$('method')){const r=$('method').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('method').close()}};
function activateRelease(name){activeRelease=name;const d=releases[name];rows=d.rows;meta=d.meta;categories=d.categories||[];Object.assign(state,{borough:'',year:'',outcome:'',category:'',cohort:'all',days:null,storeys:'',heritage:'',homes:''});filtered=[];caseIndex=0;pairIndex=0;reasonKey='';populateControls();['borough','year','outcome','category','storeys','heritage','homes'].forEach(k=>$(k).value='');const verified=rows.filter(r=>r.verified).length;$('verifiedControls').hidden=!verified;$('verifiedLabel').textContent=fmt(verified)+' document-verified cases';document.querySelector('[data-cohort="verified"] span').textContent=fmt(verified);$('cohortLabel').textContent=name==='supplied'?'Conversion screen':'Keyword candidates';$('cohortCount').textContent=fmt(rows.length);document.querySelector('[data-cohort="house"] span').textContent=fmt(rows.filter(r=>r.screen==='House wording').length);$('sidebarCoverage').innerHTML=`${fmt(rows.length)} candidates<br>${verified} plan-verified cases`;$('releaseDate').textContent=name==='supplied'?'Supplied 7 Nov 2026':'Snapshot 5 Oct 2026';$('releaseRange').textContent=name==='supplied'?'Start dates: 2019–30 Oct 2026':'Start dates: 2021–2025';$('sourceAudit').textContent=name==='supplied'?`Active release: supplied conversion extract. Query scripts and exact extraction timestamp not supplied. File SHA-256 values are listed in Data & sources.`:`Active release: Foundations. Original CSV SHA-256: ${meta.original_sha256}.`;renderSources();render();refreshCompact();}
function emptyRelease(prefix){const off=activeRelease!=='supplied';$(prefix+'Empty').hidden=!off;$(prefix+'Content').hidden=off;$(prefix+'Empty').textContent='This analysis belongs to the supplied conversion release. Choose “Conversions · supplied extract” in the data-release selector to explore it.';return off;}
function reasonLabel(key){return categories.find(c=>c.key===key)?.label||key.replaceAll('_',' ')}
function cleanText(value){let s=String(value||'');for(let i=0;i<2;i++)s=new DOMParser().parseFromString(s,'text/html').body.textContent||'';return s.replace(/\s*\|\|\s*/g,'\n\n').trim()}
function mini(label,value,note){return `<article><small>${esc(label)}</small><strong>${esc(value)}</strong><p>${esc(note)}</p></article>`}
function readRecord(id){const i=filtered.findIndex(r=>r.id===id);if(i<0)return;caseIndex=i;renderCase();showSheet('spotlight')}
function renderReasons(){if(emptyRelease('reasons'))return;const refusals=filtered.filter(r=>r.status==='Rejected'),covered=refusals.filter(r=>r.reasons?.length);$('reasonCoverage').innerHTML=mini('Selected refused applications',fmt(refusals.length),'Other outcomes excluded')+mini('With classified reason text',fmt(covered.length),`${fmt(covered.length)} / ${fmt(refusals.length)} (${refusals.length?(covered.length/refusals.length*100).toFixed(1):'0'}%)`)+mini('Without classification',fmt(refusals.length-covered.length),'Unavailable; no reason inferred');$('reasonDenom').textContent=`${fmt(covered.length)} applications are the denominator. Categories come from refusal_reasons.csv and are not new AI classifications.`;const counts=categories.map(c=>({...c,n:covered.filter(r=>r.reasons.some(x=>x.category===c.key)).length})).sort((a,b)=>b.n-a.n);$('reasonChart').innerHTML=covered.length?counts.filter(c=>c.n).map(c=>`<button class="analysis-bar ${reasonKey===c.key?'active':''}" data-reason="${c.key}" aria-pressed="${reasonKey===c.key}"><span>${esc(c.label)}</span><span class="analysis-track"><i style="width:${c.n/covered.length*100}%"></i></span><strong>${(c.n/covered.length*100).toFixed(1)}%</strong><small>${c.n}/${covered.length}</small></button>`).join(''):'<p class="empty-state">No classified refusals match these filters. If an approved outcome is selected, reset it to inspect refusals.</p>';$('reasonChart').querySelectorAll('[data-reason]').forEach(b=>b.onclick=()=>{reasonKey=reasonKey===b.dataset.reason?'':b.dataset.reason;renderReasons()});$('reasonCategory').innerHTML='<option value="">All categories</option>'+categories.map(c=>`<option value="${c.key}">${esc(c.label)}</option>`).join('');$('reasonCategory').value=reasonKey;const evidence=covered.flatMap(r=>r.reasons.filter(x=>!reasonKey||x.category===reasonKey).map(x=>({r,x})));$('reasonEvidenceTitle').textContent=`Evidence excerpts · ${fmt(evidence.length)} application/category rows`;$('reasonEvidenceRows').innerHTML=evidence.slice(0,12).map(({r,x})=>`<article class="excerpt"><div><strong>${esc(reasonLabel(x.category))}</strong><span>${esc(r.borough)} · ${esc(r.ref)}</span></div><p>“${esc(x.evidence)}”</p><button data-evidence-id="${esc(r.id)}">Inspect source record ↗</button></article>`).join('')||'<p class="micro">No evidence excerpts in this selection.</p>';$('reasonEvidenceRows').querySelectorAll('[data-evidence-id]').forEach(b=>b.onclick=()=>readRecord(b.dataset.evidenceId));if(evidence.length>12)$('reasonEvidenceRows').insertAdjacentHTML('beforeend','<p class="micro">First 12 excerpts shown. Narrow the borough, year or category to inspect others.</p>');const groups={};scopeRows('borough').filter(r=>r.status==='Rejected'&&r.reasons?.length).forEach(r=>(groups[r.borough]??=[]).push(r));const authorities=Object.entries(groups).filter(([n,rs])=>rs.length>=20).sort((a,b)=>b[1].length-a[1].length);$('reasonHeatmap').innerHTML=authorities.length?'<table class="heatmap"><thead><tr><th>Authority / n</th>'+categories.map(c=>`<th title="${esc(c.description)}">${esc(c.label)}</th>`).join('')+'</tr></thead><tbody>'+authorities.map(([name,rs])=>`<tr><th>${esc(name)} · ${rs.length}</th>`+categories.map(c=>{const n=rs.filter(r=>r.reasons.some(x=>x.category===c.key)).length;return `<td style="background:rgba(183,98,62,${n/rs.length*.8})" title="${n} / ${rs.length}">${Math.round(n/rs.length*100)}%</td>`}).join('')+'</tr>').join('')+'</tbody></table>':'<p class="micro">No authority has 20 classified refusals under these filters.</p>';}
function renderSizes(){if(emptyRelease('sizes'))return;const decided=filtered.filter(r=>['Permitted','Rejected'].includes(r.status));const measure=$('sizeMeasure').value;const usable=decided.filter(r=>Number.isFinite(r.size?.[measure])&&r.size[measure]>0);const sized=decided.filter(r=>Number.isFinite(r.size?.min_flat_m2)&&r.size.min_flat_m2>0);$('sizeCoverage').innerHTML=mini('Decided applications',fmt(decided.length),'Permitted + rejected')+mini('Usable selected area measure',fmt(usable.length),`${fmt(decided.length-usable.length)} missing / non-positive`)+mini('With reported flat size',fmt(sized.length),'Not independently plan-verified');$('sizeMeasureNote').textContent=measure==='area_per_flat_m2'?'Proxy: reported existing house area divided by parsed proposed flats. It is not a measured floor area for each flat.':'Smallest reported flat area in the supplied size extract. Some applications have incomplete flat-size schedules.';const bands=[['Under 40 m²',0,40],['40–59.9 m²',40,60],['60–79.9 m²',60,80],['80–99.9 m²',80,100],['100+ m²',100,Infinity]];$('sizeChart').innerHTML=bands.map(([label,min,max])=>{const rs=usable.filter(r=>r.size[measure]>=min&&r.size[measure]<max),s=summarize(rs),rate=s.denom?s.r/s.denom*100:null;return `<div class="size-band" title="${s.r} rejected of ${s.denom} decided"><strong>${rate===null?'—':rate.toFixed(1)+'%'}</strong><div class="size-band-track"><span style="height:${rate||0}%"></span></div><span>${label}</span><small>${s.r}/${s.denom} rejected</small></div>`}).join('');const groups=[[true,'Extractor flagged ≥1 shortfall'],[false,'No shortfall flagged']];$('standardChart').innerHTML=groups.map(([v,label])=>{const rs=decided.filter(r=>r.size?.any_below_standard===v),s=summarize(rs);return `<div class="analysis-bar static"><span>${label}</span><span class="analysis-track"><i style="width:${s.denom?s.r/s.denom*100:0}%"></i></span><strong>${s.denom?(s.r/s.denom*100).toFixed(1)+'%':'—'}</strong><small>${s.r}/${s.denom}</small></div>`}).join('');const known=decided.filter(r=>typeof r.size?.any_below_standard==='boolean'),complete=known.filter(r=>r.size.sizes_complete===true);$('standardCoverage').textContent=`${fmt(known.length)} / ${fmt(decided.length)} decided records have an extractor flag; ${fmt(decided.length-known.length)} unknown. ${fmt(complete.length)} of the flagged/assessed records have a complete reported size schedule. Bars show refused share, not the percentage failing a standard.`;}
function renderRetries(){if(emptyRelease('retries'))return;const old=activePairs[pairIndex]?.id;const byId=new Map(rows.map(r=>[r.id,r]));activePairs=(releases.supplied.pairs||[]).filter(p=>matches(byId.get(p.refusedId)));pairIndex=Math.max(0,activePairs.findIndex(p=>p.id===old));const decided=activePairs.filter(p=>['approved','refused'].includes(p.nextDecision)),approved=decided.filter(p=>p.nextDecision==='approved');$('retryCoverage').innerHTML=mini('Matched application pairs',fmt(activePairs.length),`${fmt(new Set(activePairs.map(p=>p.site)).size)} distinct matched sites`)+mini('Next application approved',decided.length?(approved.length/decided.length*100).toFixed(1)+'%':'—',`${approved.length} / ${decided.length} decided next applications`)+mini('Median gap to next start',activePairs.length?fmt(median(activePairs.map(p=>p.days)))+' days':'—','Refused decision → next application start');const counts=['approved','refused','withdrawn','pending/unknown','other'].map(k=>[k,activePairs.filter(p=>p.nextDecision===k).length]);$('retryOutcomeChart').innerHTML=counts.map(([label,n])=>`<div class="analysis-bar static"><span>${esc(label)}</span><span class="analysis-track"><i style="background:${label==='approved'?'var(--teal)':label==='refused'?'var(--terra)':'#a8b1a8'};width:${activePairs.length?n/activePairs.length*100:0}%"></i></span><strong>${fmt(n)}</strong><small>${activePairs.length?(n/activePairs.length*100).toFixed(1)+'%':'—'}</small></div>`).join('');$('pairSelect').innerHTML=activePairs.length?activePairs.map((p,i)=>`<option value="${i}">${esc(p.id+' · '+p.borough+' · '+p.nextDecision)}</option>`).join(''):'<option value="">No matching pairs</option>';renderPair();}
function median(ns){const a=ns.filter(Number.isFinite).sort((a,b)=>a-b);return a.length?(a[Math.floor((a.length-1)/2)]+a[Math.ceil((a.length-1)/2)])/2:null}
function renderPair(){const p=activePairs[pairIndex];$('prevPair').disabled=!p||pairIndex===0;$('nextPair').disabled=!p||pairIndex===activePairs.length-1;$('pairSelect').value=String(pairIndex);$('pairWarning').hidden=!p?.warnings.length;if(!p){$('pairMeta').textContent='No matched pairs under these filters. Global outcome filters apply to the refused side; reset an approved-only filter to inspect pairs.';for(const id of ['refusedPairCard','nextPairCard','pairTags','pairReasonText'])$(id).textContent='';return}const byId=new Map(rows.map(r=>[r.id,r])),a=byId.get(p.refusedId),b=byId.get(p.nextId);$('pairMeta').textContent=`${p.id} · ${p.borough} · Match: ${p.method} · ${p.days} days from refusal to next start. Match unverified.`;$('pairWarning').textContent=p.warnings.join(' ');function card(r,label,units){const url=safeUrl(r.url);return `<div class="eyebrow">${label}</div><h3>${esc(r.ref)}</h3><span class="status-pill ${r.status==='Rejected'?'rejected':''}">${esc(r.status)}</span><p>${esc(r.description)}</p><div class="pair-facts"><span>Start: ${esc(date(r.date))}</span><span>Decision: ${esc(date(r.decided))}</span><span>Parsed proposed flats: ${units===null?'Unknown':esc(units)} · unverified</span></div>${url?`<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener">Council record ↗</a>`:'<p class="micro">Council URL missing from this extract.</p>'}`} $('refusedPairCard').innerHTML=card(a,'REFUSED APPLICATION',p.refusedUnits);$('nextPairCard').innerHTML=card(b,'NEXT MATCHED APPLICATION',p.nextUnits);$('pairTags').innerHTML='<span class="micro">Description-derived tags:</span> '+p.tags.filter(Boolean).map(t=>`<span>${esc(t.replaceAll('_',' '))}</span>`).join('');const text=cleanText(p.reasonText);$('pairReasonText').textContent=text&&text.length>20?text:'No substantive refusal text supplied for this pair.';}
function renderCaseReasons(r){$('caseReasonList').innerHTML=r.reasons?.length?'<div class="eyebrow">SUPPLIED REASON EXCERPTS · RULE-CLASSIFIED</div>'+r.reasons.map(x=>`<div class="case-reason"><strong>${esc(reasonLabel(x.category))}</strong><p>“${esc(x.evidence)}”</p></div>`).join(''):'';}
function renderSources(){const supplied=activeRelease==='supplied';$('releaseInventory').innerHTML=supplied?`<div class="source-cards"><article class="panel"><span class="eyebrow">ACTIVE / SUPPLIED CONVERSION EXTRACT</span><h3>6,396 screened applications</h3><p>34 recorded authorities, including City and OPDC. Start dates: 1 January 2019–30 October 2026. Supplied on 7 November 2026; exact extraction timestamp and query/classification scripts were not supplied.</p><p>Separate from the 5,377 Foundations keyword candidates. Some false positives and duplicate schemes may remain; none is plan-verified by this app.</p><p class="micro">Raw audit: all 6,396 IDs join to the supplied 66,880-row candidate file. That 135 MB raw file is not deployed.</p></article><article class="panel"><span class="eyebrow">ENRICHMENTS / JOINED BY APPLICATION ID</span><h3>Reasons, sizes and second attempts</h3><p>4,175 category/evidence rows cover 1,283 of 2,584 refusals. Size-feature rows cover all applications, but many individual fields are missing. 1,020 matched pairs cover 844 sites.</p><p>Outcomes use the supplied cleaned decision field. Approved → Permitted; refused → Rejected. Original decision wording is retained. No existing / proposed / net dwelling count is promoted to a verified fact.</p><p class="micro">Decision-text CSV and raw records were audited locally; app reason views use supplied classification snippets and pair-level reason text.</p></article></div><div class="panel detail-panel"><h3>Supplied file manifest</h3><p class="micro">Hashes identify the exact inputs used or audited. They do not establish source extraction dates or classification accuracy.</p><div class="table-wrap"><table><thead><tr><th>File</th><th>Bytes</th><th>SHA-256</th></tr></thead><tbody>${meta.manifest.map(f=>`<tr><td>${esc(f.file)}</td><td>${fmt(f.bytes)}</td><td><code>${f.sha256}</code></td></tr>`).join('')}</tbody></table></div><p><a class="source-link" href="refusal_reasons_README.md" target="_blank" rel="noopener">Refusal classification README ↗</a> · <a class="source-link" href="resubmissions_README.md" target="_blank" rel="noopener">Resubmission matching README ↗</a></p></div><div class="audit-warning">Known extraction issue: pair P0826 records next_units=1, although the proposal lists 1 × 3-bed and 1 × 2-bed flats. The pair is flagged; its count is not silently corrected. Dwelling totals and claims of “homes blocked” are deliberately not calculated.</div>`:`<div class="panel"><span class="eyebrow">ACTIVE / FOUNDATIONS KEYWORD SNAPSHOT</span><h3>5,377 broad keyword candidates</h3><p>From 243,926 rows × 27 columns (154,035,440 bytes), snapshot dated 5 October 2026. Candidate start dates 2021–2025; 2,005 have house wording. Includes commercial/reverse conversions, amendments and conditions. Not merged with the supplied conversion release.</p><p><a class="source-link" href="https://foreman.house-london.uk/" target="_blank" rel="noopener">Foundations source ↗</a></p><p class="micro">Original CSV SHA-256: ${meta.original_sha256}</p><p class="micro">Waltham Forest has 15 approval-wording/status discrepancies among 77 candidates. Outcome reconciliation is required before interpreting borough refusal rates. Reasons, sizes and resubmissions are not joined to this release.</p></div>`;const missing=v=>v===null||v===undefined||v==='';const defs=[['Description',r=>!missing(r.description),'Text-screened, not plan-verified'],['Recorded start date',r=>!missing(r.date),'Year grouping; 2026 is partial in supplied release'],['Decision date',r=>!missing(r.decided),'Recorded endpoint'],['Usable decision interval',validTime,'Both dates + non-negative finite days'],['Council URL',r=>!!safeUrl(r.url),'Availability only; reachability not audited'],['Both coordinates',r=>!missing(r.lat)&&!missing(r.lng),'Map aggregates by authority'],['Outcome label',r=>!missing(r.status),'See release-specific mapping'],['Source storey value',r=>!missing(r.reportedStoreys),'Existing/proposed meaning not verified'],['Parsed proposed dwelling value',r=>!missing(r.reportedDwellings),'May be wrong; not net homes'],['Positive source existing dwellings',r=>r.existingUnitsField>0,'Zero/default not treated as verified zero'],['Positive source proposed dwellings',r=>r.proposedUnitsField>0,'Not independently checked'],['Reported flat-size value',r=>r.size?.min_flat_m2>0,'Partial schedules possible'],['Classified reason categories',r=>!!r.reasons?.length,'Only applicable to refusals; missing is not no reason'],['Plan-verified existing storeys',r=>r.verified&&!missing(r.storeys),'Required for verified three-storey filter'],['Verified heritage designation',r=>r.verified&&!missing(r.heritage),'Required for heritage filter'],['Verified dwelling counts',r=>r.verified&&!missing(r.existingHomes)&&!missing(r.proposedHomes),'Required for net-home totals']];$('missingnessTable').innerHTML=defs.map(([label,fn,note])=>{const n=rows.filter(fn).length;return `<tr><td>${esc(label)}</td><td>${fmt(n)} / ${fmt(rows.length)}</td><td>${fmt(rows.length-n)}</td><td>${esc(note)}</td></tr>`}).join('');}

Promise.all(['data.json','conversions-data.json','boroughs.json'].map(url=>fetch(url).then(r=>{if(!r.ok)throw new Error('Unable to load '+url);return r.json()}))).then(([foundation,supplied,b])=>{releases={foundations:foundation,supplied};boundaries=b.boroughs;$('map').setAttribute('viewBox',b.viewBox||'0 0 800 600');initControls();activateRelease('supplied');$('loadStatus').hidden=true}).catch(e=>{$('loadStatus').textContent=e.message+' Reload to retry.'});
